import { useState, type FormEvent } from 'react';
import {
  activeChips,
  CHIP_LABELS,
  withoutChip,
  ZONES,
  ZONE_LABELS,
  type ChipKey,
  type SearchCriteria,
  type Zone,
} from '../../lib/search';
import styles from './FilterChips.module.css';

/**
 * Las cinco opciones de «Campo», en el orden fijo de la spec §3. El `value` es
 * la clave estable del chip (la misma de `SearchCriteria`), la etiqueta visible
 * es la de `CHIP_LABELS` — verbatim: Ref · Marca · Qty mín · Zona · Lead time máx.
 */
const FIELD_OPTIONS: { key: ChipKey; label: string }[] = [
  { key: 'partNumber', label: CHIP_LABELS.partNumber },
  { key: 'brand', label: CHIP_LABELS.brand },
  { key: 'minQuantity', label: CHIP_LABELS.minQuantity },
  { key: 'zone', label: CHIP_LABELS.zone },
  { key: 'maxLeadTimeDays', label: CHIP_LABELS.maxLeadTimeDays },
];

interface Props {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}

/**
 * Chips de filtro de SRCH-01. Totalmente controlado: no guarda criterios, los
 * recibe y emite los nuevos enteros. El único estado propio es el del formulario
 * de «+ Filtro»: si está abierto, qué campo está elegido y qué hay tecleado.
 */
export function FilterChips({ criteria, onChange }: Props) {
  const [open, setOpen] = useState(false);
  const [field, setField] = useState<ChipKey>('partNumber');
  const [value, setValue] = useState('');

  const toggleForm = () => {
    setValue('');
    setField('partNumber');
    setOpen(!open);
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const v = value.trim();
    if (!v) return;
    let next: SearchCriteria | null = null;
    switch (field) {
      case 'partNumber':
        next = { ...criteria, partNumber: v };
        break;
      case 'brand':
        next = { ...criteria, brand: v };
        break;
      case 'minQuantity': {
        const n = Number(v);
        if (Number.isFinite(n)) next = { ...criteria, minQuantity: n };
        break;
      }
      case 'zone': {
        if (ZONES.includes(v as Zone)) next = { ...criteria, zone: v as Zone };
        break;
      }
      case 'maxLeadTimeDays': {
        const n = Number(v);
        if (Number.isFinite(n)) next = { ...criteria, maxLeadTimeDays: n };
        break;
      }
    }
    if (next === null) return;
    onChange(next);
    setValue('');
    setField('partNumber');
    setOpen(false);
  };

  return (
    <div className={styles.chipsRow}>
      {activeChips(criteria).map((chip) => (
        <span key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          {chip.value}
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </span>
      ))}
      <button type="button" className={styles.chipAdd} aria-label="Añadir filtro" onClick={toggleForm}>
        <i className="ti ti-plus" aria-hidden="true" />
        Filtro
      </button>
      {open && (
        <form className={styles.chipForm} onSubmit={handleSubmit}>
          <select
            className={styles.fieldSelect}
            aria-label="Campo"
            value={field}
            onChange={(e) => {
              setField(e.target.value as ChipKey);
              setValue('');
            }}
          >
            {FIELD_OPTIONS.map((opt) => (
              <option key={opt.key} value={opt.key}>
                {opt.label}
              </option>
            ))}
          </select>
          {field === 'zone' ? (
            <select
              className={styles.valueInput}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
            >
              <option value="">Zona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {ZONE_LABELS[z]}
                </option>
              ))}
            </select>
          ) : (
            <input
              className={styles.valueInput}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
              type={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 'number' : 'text'}
              placeholder={
                field === 'minQuantity'
                  ? 'Ej. 500'
                  : field === 'maxLeadTimeDays'
                    ? 'Ej. 7'
                    : field === 'brand'
                      ? 'SKF'
                      : '6205-2RS'
              }
            />
          )}
          <button type="submit" className={styles.submitBtn}>
            Añadir
          </button>
        </form>
      )}
    </div>
  );
}

