import {
  ageLabel,
  ageLevel,
  countryName,
  daysSince,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

/** Diez columnas: checkbox, referencia, marca, cantidad, plazo, empresa, país, antigüedad, favoritos, acciones. */
const NUM_COLUMNS = 10;

interface Props {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}

/**
 * Tabla de resultados de SRCH-01. Presentacional: pinta las filas en el orden
 * que recibe, no ordena y no carga datos. Las seis columnas ordenables llaman a
 * `onSort`; el estado de orden vive en la pantalla.
 */
export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: Props) {
  const nowValue = now ?? new Date();

  const activeAriaSort = (column: SortColumn): 'ascending' | 'descending' | undefined => {
    if (sort?.column !== column) return undefined;
    return sort.direction === 'asc' ? 'ascending' : 'descending';
  };

  const sortableTh = (column: SortColumn, label: string) => {
    const active = sort?.column === column;
    const direction = sort?.direction;
    return (
      <th
        scope="col"
        className={[
          styles.th,
          styles.sortable,
          active ? (direction === 'asc' ? styles.sortAsc : styles.sortDesc) : undefined,
        ]
          .filter(Boolean)
          .join(' ')}
        aria-sort={activeAriaSort(column)}
        onClick={() => onSort(column)}
      >
        {label}
        {active && <span aria-hidden="true">{direction === 'asc' ? ' ↑' : ' ↓'}</span>}
      </th>
    );
  };

  return (
    <div className={styles.tableWrap}>
      <table className={styles.table}>
        <thead>
          <tr>
            <th scope="col" className={`${styles.th} ${styles.thCheckbox}`}>
              <span className={styles.srOnly}>Seleccionar</span>
            </th>
            <th scope="col" className={styles.th}>
              Referencia
            </th>
            {sortableTh('brand', 'Marca')}
            {sortableTh('quantity', 'Cantidad')}
            {sortableTh('leadTime', 'Plazo')}
            <th scope="col" className={styles.th}>
              Empresa
            </th>
            {sortableTh('country', 'País')}
            {sortableTh('age', 'Antigüedad')}
            {sortableTh('favorites', 'Favoritos')}
            <th scope="col" className={styles.th}>
              Acciones
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={NUM_COLUMNS} className={styles.emptyCell}>
                No hemos encontrado stock con estos filtros.
              </td>
            </tr>
          ) : (
            rows.map((row) => {
              const days = daysSince(row.lastUploadAt, nowValue);
              const age = ageLevel(days);
              const qtyOk = meetsMinQuantity(row.quantity, minQuantity);
              return (
                <tr key={row.id} className={row.consulted ? styles.consultedRow : undefined}>
                  <td className={`${styles.td} ${styles.tdCheckbox}`}>
                    <input
                      type="checkbox"
                      className={styles.checkbox}
                      checked={selected.has(row.id)}
                      onChange={() => onToggleRow(row.id)}
                      aria-label={`Seleccionar ${row.partNumber}`}
                    />
                  </td>
                  <td className={styles.td}>
                    <span className={styles.cellRef}>{row.partNumber}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={styles.brandBadge}>{row.brand}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={`${styles.qty} ${qtyOk ? styles.qtyOk : styles.qtyLow}`}>
                      {quantityLabel(row.quantity)}
                    </span>
                  </td>
                  <td className={styles.td}>
                    <span className={styles.leadTime}>{leadTimeLabel(row.leadTimeDays)}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={styles.company}>{row.orgName}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={styles.countryBadge}>{countryName(row.country)}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={`${styles.age} ${age !== 'fresh' ? styles.ageStale : ''}`}>
                      {ageLabel(days)}
                    </span>
                  </td>
                  <td className={styles.td}>
                    <button
                      type="button"
                      className={`${styles.fav} ${row.isFavorite ? styles.favOn : ''}`}
                      aria-pressed={row.isFavorite}
                      onClick={() => onToggleFavorite(row.orgId)}
                    >
                      <span className={styles.favStar} aria-hidden="true">
                        ★
                      </span>
                      <span>{row.favoriteCount}</span>
                    </button>
                  </td>
                  <td className={styles.td}>
                    <div className={styles.actions}>
                      <button
                        type="button"
                        className={styles.consultBtn}
                        disabled
                        title={
                          row.consulted
                            ? 'Ya consultada anteriormente'
                            : 'La consulta de una sola línea llega en la próxima versión. Marca la fila y usa «Consultar seleccionados».'
                        }
                        onClick={() => onConsult(row.id)}
                      >
                        Consultar
                      </button>
                      <button
                        type="button"
                        className={styles.contactBtn}
                        disabled
                        title="El hilo libre con el proveedor está fuera del alcance de esta versión"
                        onClick={() => onContact(row.orgId)}
                      >
                        Contactar
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

