import { useCallback, useEffect, useState } from 'react';
import {
  EMPTY_CRITERIA,
  fetchResults,
  meetsMinQuantity,
  metaCounterLabel,
  nextSort,
  sortRows,
  toggleFavorite,
  type SearchCriteria,
  type SearchPage,
  type Sort,
} from '../../lib/search';
import { sendInquiries, type InquiryLine } from '../../lib/thread-detail';
import type { MemberProfile } from '../../lib/session';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

interface Props {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * Cableado VERA<->chips: fila del día 9 (out_of_scope). Esta prop es la firma
   * pública del componente (F-118) y llega cableada desde App.tsx. Se recibe
   * y se ignora: no cambia nada de lo que se pide en esta iteración.
   */
  veraCriteria?: SearchCriteria | null;
}

export function SearchResults({ profile, now = new Date(), veraCriteria }: Props) {
  void veraCriteria;

  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sendError, setSendError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [page, setPage] = useState<SearchPage>({ rows: [], total: 0, capped: false });

  const fetchPage = useCallback(() => {
    return fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria });
  }, [profile.orgId, profile.id, criteria]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await fetchPage();
      setPage(result);
    } catch {
      setError('No se pudieron cargar los resultados. Inténtalo de nuevo.');
    } finally {
      setLoading(false);
    }
  }, [fetchPage]);

  useEffect(() => {
    setSelected(new Set());
    load();
  }, [load]);

  const sortedRows = sortRows(page.rows, sort);
  const withStock = page.rows.filter((r) => meetsMinQuantity(r.quantity, criteria.minQuantity)).length;
  const allSelected = page.rows.length > 0 && page.rows.every((r) => selected.has(r.id));

  const handleToggleAll = () => {
    if (allSelected) setSelected(new Set());
    else setSelected(new Set(page.rows.map((r) => r.id)));
  };

  const handleConsultSelected = async () => {
    const lines: InquiryLine[] = page.rows
      .filter((r) => selected.has(r.id))
      .map((r) => ({ lineId: r.id, distributorOrgId: r.orgId, quantity: r.quantity }));
    if (lines.length === 0) return;
    setSending(true);
    setSendError(null);
    try {
      await sendInquiries(lines, profile.orgId);
      setSelected(new Set());
      await load();
    } catch {
      setSendError('No se pudieron enviar las consultas. Inténtalo de nuevo.');
    } finally {
      setSending(false);
    }
  };

  const handleToggleFavorite = async (orgId: string) => {
    const row = page.rows.find((r) => r.orgId === orgId);
    if (!row) return;
    try {
      await toggleFavorite(profile.id, orgId, !row.isFavorite);
      const result = await fetchPage();
      setPage(result);
    } catch {
      /* Sin estado de error definido para favoritos: no romper la pantalla. */
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</div>
      <h1 className={styles.title}>Resultados de búsqueda</h1>

      <FilterChips criteria={criteria} onChange={setCriteria} />

      <div className={styles.metabar}>
        <div className={styles.metaCount}>{metaCounterLabel(page.total, withStock, criteria.minQuantity)}</div>
        {!loading && page.rows.length > 0 && (
          <button type="button" className={styles.selectAllBtn} onClick={handleToggleAll}>
            {allSelected ? 'Deseleccionar todos' : 'Seleccionar todos'}
          </button>
        )}
        <button
          type="button"
          className={styles.consultSelectedBtn}
          disabled={selected.size === 0 || sending}
          onClick={handleConsultSelected}
        >
          Consultar seleccionados
        </button>
        <button
          type="button"
          className={styles.watcherBtn}
          disabled
          title="Los watchers llegarán en una próxima versión."
        >
          <i className="ti ti-bell-plus" aria-hidden="true" />
          Crear watcher con estos criterios
        </button>
      </div>

      {sendError && (
        <div className={styles.sendError} role="alert">
          {sendError}
        </div>
      )}

      {page.capped && (
        <div className={styles.cappedNotice} role="status">
          Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
        </div>
      )}

      <div className={styles.resultsArea} aria-busy={loading}>
        {loading ? (
          <div className={styles.spinnerWrap} role="status" aria-label="Cargando resultados">
            <div className={styles.spinner} aria-hidden="true" />
            <span className={styles.loadingText}>Cargando resultados</span>
          </div>
        ) : error ? (
          <div className={styles.errorBox} role="alert">
            <p>{error}</p>
            <button type="button" className={styles.retryBtn} onClick={() => load()}>
              Reintentar
            </button>
          </div>
        ) : (
          <ResultsTable
            rows={sortedRows}
            sort={sort}
            selected={selected}
            minQuantity={criteria.minQuantity}
            now={now}
            onSort={(column) => setSort((prev) => nextSort(prev, column))}
            onToggleRow={(lineId) =>
              setSelected((prev) => {
                const next = new Set(prev);
                if (next.has(lineId)) next.delete(lineId);
                else next.add(lineId);
                return next;
              })
            }
            onToggleFavorite={handleToggleFavorite}
            onConsult={() => {
              /* F-100: el botón de fila está apagado; el callback se conserva
                 hasta FL-MSG-01. */
            }}
            onContact={() => {
              /* F-100: el botón de fila está apagado; el callback se conserva
                 hasta FL-MSG-01. */
            }}
          />
        )}
      </div>
    </div>
  );
}
